harness.helpers:
/// Stands in for a BridgeAirlock with two independent lanes (all the guard asks of an adapter).
contract SpecAirlock {
    function independentLanes() external pure returns (uint256) { return 2; }
}
/// Stands in for ThreatRegistry's hold view: a flag per address, set by the harness.
contract SpecThreats {
    mapping(address => bool) public held;
    function set(address a, bool v) external { held[a] = v; }
    function isContractHeld(address a) external view returns (bool, uint8) { return (held[a], 1); }
}

harness.state:
SpecAirlock public inAdapter;
SpecAirlock public outAdapter;
bytes32 public constant IN = keccak256("route in");
bytes32 public constant OUT = keccak256("route out");
SpecThreats public threats;

harness.setup:
t = new BridgeGuard(address(this));
t.createToken("Bridged ETH", "bETH", 18);
t.setAudit("https://example.org/audit.pdf", bytes32(uint256(1)));
inAdapter = new SpecAirlock();
outAdapter = new SpecAirlock();
t.setRoute(IN, address(inAdapter), 600 ether, true);
t.setOutboundRoute(OUT, address(outAdapter), 400 ether, true);
threats = new SpecThreats();
t.setThreats(IContractThreats(address(threats)));
threats.set(address(0xA11CE), true);
vm.prank(address(inAdapter));
t.inbound(IN, address(0xA11CE), 1 ether); // queued: held[0]
t.setGuardian(address(0x6A2D), true);
t.setGovernance(address(0x6070));

actions.inbound:
bytes32 id = a[0] & 1 == 0 ? IN : OUT;
vm.prank(caller);
try t.inbound(id, actor(a[1]), uint256(uint128(a[2]))) { ok = true; } catch { ok = false; }

actions.outbound:
bytes32 id = a[0] & 1 == 0 ? OUT : IN;
vm.prank(caller);
try t.outbound(id, actor(a[1]), uint256(uint128(a[2]))) { ok = true; } catch { ok = false; }

harness.views:
function inToday(bytes32 id) public view returns (uint256 i) { (, , uint128 x, , uint64 day, ) = t.routes(id); i = day == block.timestamp / 1 days ? x : 0; }
function outToday(bytes32 id) public view returns (uint256 o) { (, , , uint128 x, uint64 day, ) = t.routes(id); o = day == block.timestamp / 1 days ? x : 0; }
function limitOf(bytes32 id) public view returns (uint256) { (, uint128 l, , , , ) = t.routes(id); return l < t.maxDailyLimit() ? l : t.maxDailyLimit(); }
function inRoute() external view returns (uint256) { return inToday(IN); }
function outRoute() external view returns (uint256) { return outToday(OUT); }
function inLimit() external view returns (uint256) { return limitOf(IN); }
function outLimit() external view returns (uint256) { return limitOf(OUT); }
function supply() external view returns (uint256) { return t.token().totalSupply(); }
